const adj = { A:['B','C'], B:['A','D','E'], C:['A','F'], D:['B'], E:['B','F'], F:['C','E'] };
function bfsShortestPath(source, adj) {
  const dist = {}, parent = {}, queue = [source];
  dist[source] = 0; parent[source] = null;
  while (queue.length > 0) {
    const v = queue.shift();
    for (const u of adj[v]) {
      if (!(u in dist)) {
        dist[u] = dist[v] + 1;
        parent[u] = v;
        queue.push(u);
      }
    }
  }
  return { dist, parent };
}
function reconstructPath(target, parent) {
  const path = [];
  let cur = target;
  while (cur !== null && cur !== undefined) { path.push(cur); cur = parent[cur]; }
  path.reverse();
  return path;
}
const { dist, parent } = bfsShortestPath('A', adj);
const path = reconstructPath('F', parent);
console.log(path.join(' -> ') + ' | ' + dist['F']);

